(function(root){
'use strict';
const SIZE=48,AUTOSAVE_MS=300000,KEY='borough.worlds.v1';
const TOOLS={inspect:{name:'Inspect',icon:'⌖',cost:0},road:{name:'Road',icon:'╬',cost:50},residential:{name:'Homes',icon:'⌂',cost:80},commercial:{name:'Retail',icon:'▤',cost:100},industrial:{name:'Industry',icon:'▥',cost:120},power:{name:'Power',icon:'ϟ',cost:1800,upkeep:35},water:{name:'Water',icon:'◉',cost:1200,upkeep:25},park:{name:'Park',icon:'♧',cost:300,upkeep:4},hospital:{name:'Health',icon:'✚',cost:2200,upkeep:30},school:{name:'School',icon:'▱',cost:1600,upkeep:20},office:{name:'Offices',icon:'▥',cost:160},police:{name:'Police station',icon:'◈',cost:1800,upkeep:22},fire:{name:'Fire station',icon:'♨',cost:1800,upkeep:22},garbage:{name:'Recycling center',icon:'♻',cost:1400,upkeep:18},bus:{name:'Bus depot',icon:'▣',cost:1600,upkeep:18},bulldoze:{name:'Remove',icon:'⌫',cost:10}};
function rng(seed){return()=>{seed|=0;seed=seed+0x6D2B79F5|0;let t=Math.imul(seed^seed>>>15,1|seed);t=t+Math.imul(t^t>>>7,61|t)^t;return((t^t>>>14)>>>0)/4294967296}}
function createWorld(name,terrain='river',seed=Math.floor(Math.random()*1e8)){
const random=rng(seed),tiles=[];for(let y=0;y<SIZE;y++)for(let x=0;x<SIZE;x++){
const river=34+Math.sin(y/7+seed%9)*3;
const wet=terrain==='river'?Math.abs(x-river)<2.3:terrain==='islands'?Math.sin(x/7)+Math.cos(y/8)+Math.sin((x+y)/9)>1.05:false;
tiles.push({ground:wet?'water':'land',tree:!wet&&random()<.16,type:null,level:0,people:0,variant:Math.floor(random()*4)});
}
const w={version:1,id:globalThis.crypto?.randomUUID?.()||'w'+Date.now()+random(),name:name.trim().slice(0,40)||'New Borough',terrain,seed,tiles,money:50000,day:1,tax:10,loans:0,savedAt:null,simStep:0};
for(let x=0;x<20;x++){let t=tiles[24*SIZE+x];t.ground='land';t.type='road';t.tree=false}return w;
}
function neighbors(i){let x=i%SIZE,y=Math.floor(i/SIZE);return [[x-1,y],[x+1,y],[x,y-1],[x,y+1]].filter(([a,b])=>a>=0&&b>=0&&a<SIZE&&b<SIZE).map(([a,b])=>b*SIZE+a)}
function connectedRoads(w){const visited=new Set(),queue=[];w.tiles.forEach((t,i)=>{let x=i%SIZE,y=Math.floor(i/SIZE);if(t.type==='road'&&(x===0||y===0||x===SIZE-1||y===SIZE-1)){visited.add(i);queue.push(i)}});for(let n=0;n<queue.length;n++)for(let i of neighbors(queue[n]))if(w.tiles[i].type==='road'&&!visited.has(i)){visited.add(i);queue.push(i)}return visited}
function analyze(w){const roads=connectedRoads(w),counts={},active=[];let population=0,jobs=0,upkeep=0;w.tiles.forEach((t,i)=>{if(t.type){counts[t.type]=(counts[t.type]||0)+1;upkeep+=TOOLS[t.type]?.upkeep||0;if(t.type==='road')upkeep+=.6}if(t.type&&neighbors(i).some(n=>roads.has(n)))active.push(i);population+=t.people||0;if(t.type==='commercial')jobs+=t.level*8;if(t.type==='industrial')jobs+=t.level*12;if(t.type==='office')jobs+=t.level*15});
let power=active.filter(i=>w.tiles[i].type==='power').length*650,water=active.filter(i=>w.tiles[i].type==='water').length*500;
let utilityNeed=population+jobs*.5;let connected={};for(let i of active){let t=w.tiles[i];connected[t.type]=(connected[t.type]||0)+1}let services=Math.min(20,(connected.park||0)*2+(connected.hospital||0)*4+(connected.school||0)*3+(connected.police||0)*3+(connected.fire||0)*2);let pollution=Math.min(100,(counts.industrial||0)*3-(connected.garbage||0)*15);pollution=Math.max(0,pollution);let traffic=Math.min(100,Math.round(population/Math.max(1,[...roads].reduce((n,i)=>n+(w.tiles[i].roadWidth===2?2:1),0))*4/(1+(connected.bus||0)*.4)));let coverage={health:Math.min(100,(connected.hospital||0)*400/Math.max(1,population)*100),education:Math.min(100,(connected.school||0)*300/Math.max(1,population)*100),safety:Math.min(100,(connected.police||0)*500/Math.max(1,population)*100),fire:Math.min(100,(connected.fire||0)*500/Math.max(1,population)*100),garbage:Math.min(100,(connected.garbage||0)*600/Math.max(1,population)*100)};
let happiness=Math.max(10,Math.min(98,82+services-(w.tax-10)*2-(power<utilityNeed?25:0)-(water<utilityNeed?25:0)-(population>jobs*2+80?10:0)-pollution*.2-(traffic>70?8:0)));
let taxes=population*w.tax*.065+jobs*.35,repayment=w.loans>0?100:0,income=taxes-upkeep-repayment;
return {roads,active,counts,connected,pollution,traffic,coverage,population,jobs,power,water,utilityNeed,happiness,upkeep,taxes,repayment,income,demand:[Math.max(5,Math.min(100,80+(jobs-population*.45)*.8-(w.tax-10)*5)),Math.max(5,Math.min(100,40+(population-jobs)*.8)),Math.max(5,Math.min(100,60+(population*.5-jobs)*.8))]};
}
function place(w,x,y,tool,options={}){if(x<0||y<0||x>=SIZE||y>=SIZE||!TOOLS[tool])return{ok:false,reason:'Outside the city limits'};const i=y*SIZE+x,t=w.tiles[i];if(tool==='inspect')return{ok:true,tile:t};if(tool==='bulldoze'){if(!t.type)return{ok:false,reason:'Nothing to remove'};if(w.money<10)return{ok:false,reason:'Not enough funds'};w.money-=10;t.type=null;t.level=0;t.people=0;return{ok:true}}
if(t.type===tool)return{ok:false,reason:''};if(t.type)return{ok:false,reason:'Remove the existing building first'};if(t.ground==='water'&&tool!=='road')return{ok:false,reason:'Build on dry land'};const cost=TOOLS[tool].cost*(t.ground==='water'?4:1)*(tool==='road'&&options.roadWidth===2?2:1);if(w.money<cost)return{ok:false,reason:'Not enough funds'};w.money-=cost;t.type=tool;t.tree=false;t.level=['residential','commercial','industrial','office'].includes(tool)?0:1;if(tool==='road')t.roadWidth=options.roadWidth===2?2:1;if(['residential','commercial','office'].includes(tool))t.density=options.density==='high'?'high':'low';return{ok:true};}
function tick(w){w.day++;w.simStep++;const a=analyze(w);w.money=Math.round((w.money+a.income)*100)/100;if(w.loans>0)w.loans=Math.max(0,w.loans-100);const random=rng(w.seed+w.simStep*997);for(let i of a.active){const t=w.tiles[i];if(!['residential','commercial','industrial','office'].includes(t.type))continue;let kind=t.type==='office'?2:['residential','commercial','industrial'].indexOf(t.type),ready=a.power>0&&a.water>0&&a.power>=a.utilityNeed&&a.water>=a.utilityNeed;if(ready&&random()<a.demand[kind]/180&&a.happiness>35){t.level=Math.min(t.density==='low'?2:5,t.level+1);if(t.type==='residential')t.people=Math.min(t.level*8,(t.people||0)+4)}else if(!ready&&t.people>0&&random()<.15)t.people=Math.max(0,t.people-2)}return analyze(w)}
function valid(w){return w&&w.version===1&&typeof w.id==='string'&&typeof w.name==='string'&&w.name.length<=40&&['river','islands','plains'].includes(w.terrain)&&Number.isInteger(w.seed)&&Number.isFinite(w.money)&&Number.isFinite(w.day)&&Number.isInteger(w.tax)&&w.tax>=5&&w.tax<=25&&Number.isFinite(w.loans)&&w.loans>=0&&Number.isFinite(w.simStep)&&Array.isArray(w.tiles)&&w.tiles.length===SIZE*SIZE&&w.tiles.every(t=>t&&['land','water'].includes(t.ground)&&(t.type===null||Object.hasOwn(TOOLS,t.type)&&!['inspect','bulldoze'].includes(t.type))&&Number.isInteger(t.level)&&t.level>=0&&t.level<=5&&Number.isFinite(t.people)&&t.people>=0&&t.people<=40&&Number.isInteger(t.variant)&&t.variant>=0&&t.variant<=3)}
class WorldStore{constructor(storage){this.storage=storage;this.worlds=[];this.currentId=null;this.load()}load(){const raw=this.storage.getItem(KEY);if(!raw)return;let d;try{d=JSON.parse(raw)}catch{throw Error('Saved worlds could not be read. Export or restore a backup before resetting browser storage.')}if(!Array.isArray(d.worlds)||!d.worlds.every(valid))throw Error('Saved data is invalid; existing storage was kept.');this.worlds=d.worlds;this.currentId=d.currentId}persist(){const payload=JSON.stringify({version:1,currentId:this.currentId,worlds:this.worlds});this.storage.setItem(KEY,payload);if(this.storage.getItem(KEY)!==payload)throw Error('Save verification failed')}save(w,now=Date.now()){if(!valid(w))throw Error('World could not be saved: invalid data');let old=w.savedAt;w.savedAt=now;const i=this.worlds.findIndex(x=>x.id===w.id),prev=i>=0?this.worlds[i]:null;const snapshot=JSON.parse(JSON.stringify(w));if(i<0)this.worlds.push(snapshot);else this.worlds[i]=snapshot;let oldId=this.currentId;this.currentId=w.id;try{this.persist()}catch(e){w.savedAt=old;this.currentId=oldId;if(i<0)this.worlds.pop();else this.worlds[i]=prev;throw e}return now}get(id){const w=this.worlds.find(x=>x.id===id);return w?JSON.parse(JSON.stringify(w)):null}remove(id){const prior=this.worlds;this.worlds=this.worlds.filter(w=>w.id!==id);try{this.persist()}catch(e){this.worlds=prior;throw e}}}
class GameSession{constructor(store){this.store=store;this.world=null;this.screen='home';this.paused=true;this.speed=1}start(id){if(this.screen==='game')this.save();const w=this.store.get(id);if(!w)throw Error('World not found');this.world=w;this.screen='game';this.paused=false;this.speed=1;return w}save(now=Date.now()){if(!this.world)return null;return this.store.save(this.world,now)}exit(now=Date.now()){this.save(now);this.screen='home';this.paused=true}step(){if(this.screen!=='game'||this.paused)return false;for(let i=0;i<this.speed;i++)tick(this.world);return true}}
function lineTiles(a,b){let x=a.x,y=a.y;const out=[{x,y}],dx=Math.abs(b.x-x),dy=Math.abs(b.y-y),sx=Math.sign(b.x-x),sy=Math.sign(b.y-y);let ix=0,iy=0;while(ix<dx||iy<dy){if(ix<dx&&(iy===dy||(ix+.5)/Math.max(1,dx)<(iy+.5)/Math.max(1,dy))){x+=sx;ix++}else{y+=sy;iy++}out.push({x,y})}return out}
function buildRoad(w,a,b,options={}){const tiles=lineTiles(a,b);let cost=0;for(let p of tiles){if(p.x<0||p.y<0||p.x>=SIZE||p.y>=SIZE)return{ok:false,reason:'Outside city limits'};let t=w.tiles[p.y*SIZE+p.x];if(t.type&&t.type!=='road')return{ok:false,reason:'Road blocked by a building'};if(!t.type)cost+=TOOLS.road.cost*(t.ground==='water'?4:1)*(options.roadWidth===2?2:1)}if(w.money<cost)return{ok:false,reason:'Not enough funds'};for(let p of tiles)place(w,p.x,p.y,'road',options);return{ok:true,cost,tiles:tiles.length}}
const api={lineTiles,buildRoad,GameSession,SIZE,AUTOSAVE_MS,KEY,TOOLS,createWorld,neighbors,analyze,place,tick,valid,WorldStore};if(typeof module!=='undefined')module.exports=api;else root.CityEngine=api;
})(globalThis);
